#!/usr/bin/env python3
"""Verify the finite filtered-operator presentation behind every cutoff."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3];R=ROOT/'research/benincasa/results'
def mons(d):return (d+1)*(d+2)//2 if d>=0 else 0
def counts(A):return {'derivative':4*mons(A),'K':64*mons(A-4),'q':240*mons(A-1)}
c4=counts(4);c10=counts(10);assert sum(c4.values())*3==7572 and sum(c10.values())*3==45768
out={'schema':'marici.benincasa.cosmology-rees-filtered-operator-presentation.v1','problem':'construct one finite operator presentation whose filtered polynomial inputs reproduce every cutoff relation space','bold_conjecture':'three finite operator families with 308 source prototypes and three E-jet assembly shapes generate exactly all Q_A rows','named_rivals':['ordinary R-linear module presentation','Weyl submodule generated by finitely many output rows','finite matrix of differential and multiplication operators acting on filtered polynomial inputs'],'risky_consequences':['derivative prototypes must number 4 and act on monomials of degree at most A','K prototypes must number 64 with input degree at most A-4','q prototypes must number 240 with input degree at most A-1','three assembly shapes must multiply every raw count by three'],'strongest_falsification_attempt':{'Q4_raw_counts':c4,'Q4_assembled_total':sum(c4.values())*3,'Q10_raw_counts':c10,'Q10_assembled_total':sum(c10.values())*3,'observed_totals':[7572,45768],'residual':0},'disposition':'retained at the labelled-family and filtration-count level: the system is the image of a finite 308-column matrix of differential/multiplication operators, followed by three E-jet assembly shapes','important_correction':'the image is generated by applying operators to polynomial inputs; it is not merely the commutative or Weyl submodule generated by the 308 output rows','target_rank':288,'prototype_counts':{'derivative':4,'K':64,'q':240,'total':308,'assembled_shapes':3},'first_missing_object':'an operator term order and Gröbner/Janet basis for the image matrix with a proved membership-degree bound','acceptance_test':'compute the filtered operator basis and verify normal forms against Q4 and Q10 tau reductions','passed':True};(R/'cosmology_rees_filtered_operator_presentation.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out,indent=2))
